import { Match as M, Option, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Toast from "../../ui/base-ui-toast";

// MODEL

export const Model = S.Struct({
  toast: Toast.Model,
});
export type Model = typeof Model.Type;

// MESSAGE

export const ClickedShowToast = m("ClickedShowToast");
export const GotToastMessage = m("GotToastMessage", {
  message: Toast.Message,
});

export const Message = S.Union([ClickedShowToast, GotToastMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [
  {
    toast: Toast.init({ id: "toast-basic" }),
  },
  [],
];

// UPDATE

const updateToast = (
  model: Model,
  toast: Toast.Model,
  commands: readonly Command.Command<Toast.Message>[]
): readonly [Model, readonly Command.Command<Message>[]] => [
  evo(model, {
    toast: () => toast,
  }),
  Command.mapMessages(commands, (message) => GotToastMessage({ message })),
];

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ClickedShowToast: () => {
        const [toast, commands] = Toast.show(model.toast, {
          variant: "Success",
          sticky: true,
          payload: {
            title: "Toast 1 created",
            maybeDescription: Option.some("This is a toast notification."),
          },
        });

        return updateToast(model, toast, commands);
      },
      GotToastMessage: ({ message }) => {
        const [toast, commands] = Toast.update(model.toast, message);

        return updateToast(model, toast, commands);
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.button(
        [
          h.Type("button"),
          h.Class(
            "inline-flex cursor-pointer items-center rounded-lg border border-gray-300 bg-white px-4 py-2 text-sm font-medium text-gray-900 transition hover:bg-gray-100"
          ),
          h.OnClick(ClickedShowToast()),
        ],
        ["Create toast"]
      ),
      h.submodel({
        slotId: model.toast.id,
        model: model.toast,
        view: Toast.view,
        viewInputs: {
          position: "BottomRight",
          entryToView: Toast.baseUiToastEntryView,
          entryClassName: Toast.baseUiToastEntryClassName,
          containerClassName: Toast.baseUiToastContainerClassName,
        },
        toParentMessage: (message) => GotToastMessage({ message }),
      }),
    ]
  );
});

import { Scene, Ui } from "foldkit";
import { describe, test } from "vitest";

import * as Toast from "../../ui/base-ui-toast";
import * as BaseUiToastBasicExample from "./main";

const toAnimationMessage = (message: Ui.Animation.Message) =>
  BaseUiToastBasicExample.GotToastMessage({
    message: Toast.GotAnimationMessage({
      entryId: "toast-basic-entry-0",
      message,
    }),
  });

const resolveEntryAnimation = () =>
  Scene.Command.resolveAll(
    [
      Ui.Animation.RequestFrame,
      Ui.Animation.AdvancedAnimationFrame(),
      toAnimationMessage,
    ],
    [
      Ui.Animation.WaitForAnimationSettled({ id: "toast-basic-entry-0" }),
      Ui.Animation.EndedAnimation(),
      toAnimationMessage,
    ]
  );

describe("Base UI toast Basic example", () => {
  test("shows a sticky toast and marks it for dismissal", () => {
    Scene.scene(
      {
        update: BaseUiToastBasicExample.update,
        view: BaseUiToastBasicExample.view,
      },
      Scene.with(BaseUiToastBasicExample.init()[0]),
      Scene.click(Scene.role("button", { name: "Create toast" })),
      resolveEntryAnimation(),
      Scene.expect(Scene.role("status")).toExist(),
      Scene.expect(Scene.text("Toast 1 created")).toExist(),
      Scene.expect(Scene.text("This is a toast notification.")).toExist(),
      Scene.click(Scene.role("button", { name: "Dismiss Toast 1 created" })),
      Scene.expect(Scene.role("status")).toHaveAttr("data-leave", ""),
      resolveEntryAnimation()
    );
  });
});
